style.css:
/* 隐藏所有网站的 Favicon */
link[rel="icon"],
link[rel="shortcut icon"],
link[rel="apple-touch-icon"],
link[rel="manifest"] {
    display: none !important;
}

/* 仅隐藏 TradingView 的 Favicon */
@-moz-document domain("tradingview.com") {
link[rel="icon"],
    link[rel="manifest"],
    link[rel="apple-touch-icon"] {
        display: none !important;
    }
}
